          hits.length,
          entry.key.contains('mobile') ? 2 : 1,
          reason:
              '${entry.key} must carry ${entry.value == 'Checkout repository from local mirror' ? 'two (build-ios + submit-ios)' : 'one (build-macos)'} '
              'inline checkout step(s) named "${entry.value}" (gh-1600)',
