            script,
            contains(r'rm -rf "$GITHUB_WORKSPACE" || true'),
            reason:
                'the clean must TOLERATE unremovable paths (bench leftovers '
                'held by docker) — a bare rm -rf failing the checkout was the '
                'gh-1600 trigger ($entry.key)',
          );

